import { Hono } from '$PWD/src/hono'
import { validator } from '$PWD/src/validator'

const run = async (label: string, fn: () => Promise<unknown>) => {
  try { console.log(label, JSON.stringify(await fn())) } catch (e) { console.log(label, 'THREW', String(e)) }
}

// 1) native platform behavior with mixed-case multipart
await run('native Request.formData Multipart/Form-Data', async () => {
  const fd = new FormData(); fd.append('a', '1')
  const src = new Request('http://x/', { method: 'POST', body: fd })
  const ct = src.headers.get('content-type')!.replace('multipart/form-data', 'Multipart/Form-Data')
  const r = new Request('http://x/', { method: 'POST', body: await src.arrayBuffer(), headers: { 'content-type': ct } })
  return Object.fromEntries(await r.formData())
})

const app = new Hono()
app.post('/fd-then-parse', async (c) => { await c.req.formData(); return c.json(await c.req.parseBody()) })
app.post('/parse-then-fd', async (c) => { await c.req.parseBody(); return c.json(Object.fromEntries(await c.req.formData())) })
app.post('/text-then-parse', async (c) => { await c.req.text(); return c.json(await c.req.parseBody()) })
app.post('/validator-then-parse', validator('form', (v) => v), async (c) => c.json(await c.req.parseBody()))
app.post('/parse-twice', async (c) => { await c.req.parseBody(); return c.json(await c.req.parseBody()) })

for (const path of ['/fd-then-parse', '/parse-then-fd', '/text-then-parse', '/validator-then-parse', '/parse-twice']) {
  const fd = new FormData(); fd.append('a', '1')
  await run('multipart ' + path, async () => { const r = await app.request(path, { method: 'POST', body: fd }); return [r.status, await r.text()] })
  const p = new URLSearchParams({ a: '1' })
  await run('urlenc ' + path, async () => { const r = await app.request(path, { method: 'POST', body: p }); return [r.status, await r.text()] })
}
EOF
